//! EXEC task partitioner (FR-4a).
//!
//! Current strategy: a deterministic topological order (Kahn's algorithm,
//! ties broken by ascending node id) dealt round-robin across N partitions.
//! Round-robin dealing trivially matches the greedy baseline cut of AC-4.2
//! and keeps fan-out splits within +-1 node (AC-4.3); output depends only on
//! the graph and N (AC-4.4). Spectral bisection of `L_dag` replaces the
//! dealing step in M2.x; cut-weight reporting (AC-4.2) lands with it.

use std::collections::{BTreeSet, HashMap};

use crate::ir::{Failed, Graph, NodeId};
use crate::store::Oref;

/// Partition the graph's nodes into N sets.
///
/// Contract: the N sets are disjoint and cover every node exactly once;
/// inside one set, nodes appear in dependency-respecting order (a producer
/// precedes its consumers whenever both land in the same set). Partitioning
/// happens once per call at submission time (AC-4.1).

display.text:
//! EXEC task partitioner (FR-4a).
//!
//! Current strategy: a deterministic topological order (Kahn's algorithm,
//! ties broken by ascending node id) dealt round-robin across N partitions.
//! Round-robin dealing trivially matches the greedy baseline cut of AC-4.2
//! and keeps fan-out splits within +-1 node (AC-4.3); output depends only on
//! the graph and N (AC-4.4). Spectral bisection of `L_dag` replaces the
//! dealing step in M2.x; cut-weight reporting (AC-4.2) lands with it.

use std::collections::{BTreeSet, HashMap};

use crate::ir::{Failed, Graph, NodeId};
use crate::store::Oref;

/// Partition the graph's nodes into N sets.
///
/// Contract: the N sets are disjoint and cover every node exactly once;
/// inside one set, nodes appear in dependency-respecting order (a producer
/// precedes its consumers whenever both land in the same set). Partitioning
/// happens once per call at submission time (AC-4.1).
pub fn bisect(graph: &Graph, parts: usize) -> Result<Vec<Vec<NodeId>>, Failed> {
    if parts == 0 {
        return Err(Failed::TypeMismatch {
            node: 0,
            expected: "parts >= 1".to_string(),
            got: "0".to_string(),
        });
    }

    let producer: HashMap<Oref, NodeId> = graph.nodes.iter().map(|n| (n.output, n.id)).collect();

    let mut in_degree: HashMap<NodeId, usize> = HashMap::new();
    let mut consumers: HashMap<NodeId, Vec<NodeId>> = HashMap::new();
    for node in &graph.nodes {
        in_degree.entry(node.id).or_insert(0);
        for input in &node.inputs {
            if let Some(src) = producer.get(input).copied() {
                *in_degree.entry(node.id).or_insert(0) += 1;
                consumers.entry(src).or_default().push(node.id);
            }
        }
    }
    for neighbors in consumers.values_mut() {
        neighbors.sort_unstable();
    }

    let mut ready: BTreeSet<NodeId> = in_degree
        .iter()
        .filter(|(_, degree)| **degree == 0)
        .map(|(&id, _)| id)
        .collect();

    let mut topo: Vec<NodeId> = Vec::with_capacity(graph.nodes.len());
    while !ready.is_empty() {
        let id = *ready.first().expect("ready set is non-empty at loop entry");
        ready.remove(&id);
        topo.push(id);
        if let Some(neighbors) = consumers.get(&id) {
            for &dst in neighbors {
                let degree = in_degree
                    .get_mut(&dst)
                    .expect("in_degree entry exists for every edge target");
                *degree -= 1;
                if *degree == 0 {
                    ready.insert(dst);
                }
            }
        }
    }
    debug_assert_eq!(topo.len(), graph.nodes.len(), "graph must be acyclic");

    let mut sets: Vec<Vec<NodeId>> = (0..parts).map(|_| Vec::new()).collect();
    for (i, id) in topo.into_iter().enumerate() {
        sets[i % parts].push(id);
    }
    Ok(sets)
}

