//! Deterministic latent-matrix workload generator (M3.1).
//!
//! Produces cluster-rich latent matrices with planted basins: every row is
//! bound to one basin; each basin owns a seeded unit-vector centroid and row
//! entries are centroid + small Gaussian noise. Generation is a pure
//! function of [`LatentSpec`], so repeated runs are bit-identical (AC-4.4).
//! The PRNG is a hand-tuned SplitMix64 with Box-Muller normals; no external
//! rand dependency, so the bit stream cannot drift with dependency bumps.

use smartcore::linalg::basic::matrix::DenseMatrix;

/// Fixed benchmark seed (house convention).
pub const SEED: u64 = 3407;

/// Intra-basin Gaussian noise scale.
const NOISE_SIGMA: f64 = 0.05;

/// The predefined benchmark shapes, largest first (M3.1):
/// 100K x 10K f64 = 8 GiB, 50K x 5K = 2 GiB, 10K x 1K = 80 MiB.
pub const SHAPE_LADDER: [(usize, usize); 3] = [(100_000, 10_000), (50_000, 5_000), (10_000, 1_000)];

/// Default planted-basin count for benchmark shapes.
pub const BENCHMARK_BASINS: usize = 16;

/// Parameters of a generated latent matrix.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LatentSpec {
    /// Number of items (matrix rows).
    pub rows: usize,
    /// Number of latent features (matrix columns).
    pub cols: usize,
    /// Planted basins; item `i` belongs to basin `i % basins`.
    pub basins: usize,
    /// PRNG seed.
    pub seed: u64,
}

struct SplitMix64(u64);

impl SplitMix64 {
    fn next_u64(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    fn next_unit(&mut self) -> f64 {
        (self.next_u64() >> 11) as f64 / (1u64 << 53) as f64
    }

    /// Standard normal via Box-Muller (cosine branch only; one draw pair
    /// yields one sample keeps the stream simple to reason about).
    fn next_normal(&mut self) -> f64 {
        let u1 = self.next_unit().max(1e-12);
        let u2 = self.next_unit();
        (-2.0 * u1.ln()).sqrt() * (std::f64::consts::TAU * u2).cos()
    }
}

fn centroids(spec: &LatentSpec, rng: &mut SplitMix64) -> Vec<Vec<f64>> {
    let mut out = vec![vec![0.0f64; spec.cols]; spec.basins];
    for basin in out.iter_mut() {
        let mut norm_sq = 0.0f64;
        for entry in basin.iter_mut() {
            *entry = rng.next_normal();
            norm_sq += *entry * *entry;
        }
        let norm = norm_sq.sqrt().max(1e-12);
        for entry in basin.iter_mut() {
            *entry /= norm;
        }
    }
    out
}

/// Generate the latent matrix in items x features orientation (row-major).
pub fn generate(spec: &LatentSpec) -> DenseMatrix<f64> {
    let mut rng = SplitMix64(spec.seed);
    let cents = centroids(spec, &mut rng);
    let mut data = Vec::with_capacity(spec.rows * spec.cols);
    for row in 0..spec.rows {
        let basin = &cents[row % spec.basins];
        for &centroid in basin.iter() {
            data.push(centroid + NOISE_SIGMA * rng.next_normal());
        }
    }
    DenseMatrix::new(spec.rows, spec.cols, data, false).expect("shape matches allocated data")
}

/// Generate the same latent space already transposed (features x items,
/// column-major storage) without an intermediate copy, matching the
/// orientation arrowspace's `build_laplacian_matrix` consumes.
pub fn generate_transposed(spec: &LatentSpec) -> DenseMatrix<f64> {
    let mut rng = SplitMix64(spec.seed);
    let cents = centroids(spec, &mut rng);
    let mut data = vec![0.0f64; spec.rows * spec.cols];
    for row in 0..spec.rows {
        let basin = &cents[row % spec.basins];
        for j in 0..spec.cols {
            data[j * spec.rows + row] = basin[j] + NOISE_SIGMA * rng.next_normal();
        }
    }
    DenseMatrix::new(spec.cols, spec.rows, data, true).expect("shape matches allocated data")
}

/// Select the largest benchmark shape whose byte size fits within
/// `available_bytes / 3` (the 0.33 rule from M3.1). The smallest ladder
/// shape is the unconditional floor.
pub fn select_benchmark_shape(available_bytes: usize) -> LatentSpec {
    let budget = available_bytes / 3;
    let &(rows, cols) = SHAPE_LADDER
        .iter()
        .find(|&&(r, c)| r * c * std::mem::size_of::<f64>() <= budget)
        .unwrap_or(&SHAPE_LADDER[SHAPE_LADDER.len() - 1]);
    LatentSpec {
        rows,
        cols,
        basins: BENCHMARK_BASINS,
        seed: SEED,
    }
}

