fn log_det_spd(a: &[Vec<f64>]) -> f64 {
    let n = a.len();
    let mut l = vec![vec![0.0; n]; n];
    for i in 0..n {
        for j in 0..=i {
            let mut s = a[i][j];
            for k in 0..j { s -= l[i][k]*l[j][k]; }
            if i == j {
                let lii = s.sqrt();  // SPD guaranteed
                l[i][j] = lii;
            } else {
