//! Cross-language parity: the Rust epiplexity port must reproduce the
//! Python reference (`epiplexity` v0.5.0) on committed fixtures.
//!
//! Expected values are pinned in `tests/fixtures/epiplexity_parity.json`,
//! generated by `tests/fixtures/gen_parity.py` with the reference
//! implementation. Regenerate after intentional semantic changes:
//!
//! ```text
//! /Users/tuned-silicon/papers/graph-wiring-epiplexity/.venv/bin/python \
//!     tests/fixtures/gen_parity.py tests/fixtures/epiplexity_parity.json
//! ```

mod common;

use common::{complete_jittered, path_laplacian, signals_ramp, signals_rough, signals_structured, two_cliques};
use smartcore_orchestrator::{EpiplexityEngine, Lgmrf};
use serde_json::Value;
use sprs::CsMat;

const PARITY_JSON: &str = include_str!("fixtures/epiplexity_parity.json");

fn laplacian_for(name: &str) -> CsMat<f64> {
    match name {
        "clique_smooth" => two_cliques(6),
        "complete_rough" => complete_jittered(12),
        "path_ramp" => path_laplacian(16),
        other => panic!("unknown parity case: {other}"),
    }
}

fn signals_for(name: &str) -> Vec<Vec<f64>> {
    match name {
        "clique_smooth" => signals_structured(6, 16),
        "complete_rough" => signals_rough(12, 16),
        "path_ramp" => signals_ramp(16, 16),
        other => panic!("unknown parity case: {other}"),
    }
}

fn approx_eq(a: f64, b: f64, ctx: &str) {
    assert!(
        (a - b).abs() <= 1e-9 * b.abs().max(1.0),
        "{ctx}: rust={a} python={b}"
    );
}

#[test]
fn structural_bits_match_python_exactly() {
    let doc: Value = serde_json::from_str(PARITY_JSON).expect("valid parity fixture");
    for case in doc["cases"].as_array().expect("cases array") {
        let name = case["name"].as_str().unwrap();
        let model = Lgmrf::new(
            &laplacian_for(name),
            case["beta"].as_f64().unwrap(),
            case["gamma"].as_f64().unwrap(),
            case["c0"].as_u64().unwrap() as usize,
            case["k"].as_u64().unwrap() as usize,
            case["b"].as_u64().unwrap() as u32,
        );
        assert_eq!(
            model.description_length_bits(),
            case["s_t_bits"].as_f64().unwrap(),
            "{name}: S_T diverges from reference"
        );
    }
}

#[test]
fn per_item_entropies_match_python_within_tolerance() {
    let doc: Value = serde_json::from_str(PARITY_JSON).expect("valid parity fixture");
    for case in doc["cases"].as_array().expect("cases array") {
        let name = case["name"].as_str().unwrap();
        let rows = signals_for(name);
        let refs: Vec<&[f64]> = rows.iter().map(|s| s.as_slice()).collect();
        let model = Lgmrf::new(
            &laplacian_for(name),
            case["beta"].as_f64().unwrap(),
            case["gamma"].as_f64().unwrap(),
            case["c0"].as_u64().unwrap() as usize,
            case["k"].as_u64().unwrap() as usize,
            case["b"].as_u64().unwrap() as u32,
        );
        let engine = EpiplexityEngine::new(&model, &refs);
        let py_h = case["h_t_bits"].as_array().expect("h_t_bits array");
        assert_eq!(engine.entropy_bits().len(), py_h.len(), "{name}: item count");
        for (i, (&rust_v, py_v)) in engine.entropy_bits().iter().zip(py_h).enumerate() {
            approx_eq(rust_v, py_v.as_f64().unwrap(), &format!("{name}[{i}] H_T"));
        }
    }
}

#[test]
fn mdl_ratio_and_verdict_match_python() {
    let doc: Value = serde_json::from_str(PARITY_JSON).expect("valid parity fixture");
    for case in doc["cases"].as_array().expect("cases array") {
        let name = case["name"].as_str().unwrap();
        let rows = signals_for(name);
        let refs: Vec<&[f64]> = rows.iter().map(|s| s.as_slice()).collect();
        let model = Lgmrf::new(
            &laplacian_for(name),
            case["beta"].as_f64().unwrap(),
            case["gamma"].as_f64().unwrap(),
            case["c0"].as_u64().unwrap() as usize,
            case["k"].as_u64().unwrap() as usize,
            case["b"].as_u64().unwrap() as u32,
        );
        let engine = EpiplexityEngine::new(&model, &refs);

        assert_eq!(
            engine.raw_bits_total(),
            case["raw_bits"].as_f64().unwrap(),
            "{name}: raw bits diverge"
        );
        approx_eq(
            engine.total_entropy_bits(),
            case["total_entropy_bits"].as_f64().unwrap(),
            &format!("{name} total H_T"),
        );
        approx_eq(
            engine.mdl_total_bits(),
            case["mdl_bits"].as_f64().unwrap(),
            &format!("{name} MDL"),
        );
        approx_eq(
            engine.compression_ratio(),
            case["ratio"].as_f64().unwrap(),
            &format!("{name} ratio"),
        );
        assert_eq!(
            engine.verdict().as_str(),
            case["verdict"].as_str().unwrap(),
            "{name}: verdict diverges"
        );
    }
}

