fn step2_calinski_harabasz(rows: &[Vec<f64>], k_min: usize, k_max: usize, base_seed: u64) -> usize {
    let n = rows.len();
    if n < 10 { return k_min; }
    let range = k_max - k_min;
    let step = if range <= 5 { 1 } else if range <= 15 { 2 } else { 3 };
    let candidates: Vec<usize> = (k_min..=k_max).step_by(step).collect();

    let mut scored: Vec<(usize, f64)> = candidates.iter().copied()
        .filter(|&k| k < n && k >= 2)
        .map(|k| {
            let mut best = f64::NEG_INFINITY;
            for trial in 0..CH_TRIALS {
                let seed = base_seed.wrapping_add((k as u64)*1000).wrapping_add(trial as u64);
                let assignments = kmeans_lloyd(rows, k, MAX_ITER, seed);
                let ch = calinski_harabasz_score(rows, &assignments, k);
                best = best.max(ch);
            }
            let penalized = best - CH_PENALTY * (k as f64) * (n as f64).ln();
            (k, penalized)
        })
        .collect();

    let (mut best_k, mut best_score) = pick_best(&scored).unwrap_or((k_min, f64::NEG_INFINITY));

    if step > 1 {
        let fine: Vec<usize> = [best_k.wrapping_sub(step-1), best_k.saturating_sub(1), best_k, (best_k+1).min(k_max), (best_k+step-1).min(k_max)]
            .into_iter()
            .filter(|&k| k >= k_min && k <= k_max && k < n && !candidates.contains(&k))
            .collect();
        // dedup
        ...
        let fine_scored = same scoring with seed base + k*10000 + trial;
        if let Some((fk, fs)) = pick_best(&fine_scored) { if fs > best_score { best_k=fk; best_score=fs; } }
    }
    if best_k < k_max { best_k } else { k_max }
}

fn pick_best(scored: &[(usize,f64)]) -> Option<(usize,f64)> {
    scored.iter().copied().max_by(|a,b| match a.1.partial_cmp(&b.1) { Some(o) if o != Ordering::Equal => o, _ => a.0.cmp(&b.0) })
}
```
