use smartcore_orchestrator::kmeans_lloyd;

fn ch(rows: &[Vec<f64>], a: &[usize], k: usize) -> f64 {
    let n = rows.len(); let f = rows[0].len();
    if k <= 1 || k >= n { return 0.0; }
    let g: Vec<f64> = (0..f).map(|j| rows.iter().map(|r| r[j]).sum::<f64>() / n as f64).collect();
    let mut cents = vec![vec![0.0; f]; k]; let mut cnt = vec![0usize; k];
    for (i, r) in rows.iter().enumerate() { let c = a[i]; if c < k { cnt[c] += 1;
        for j in 0..f { cents[c][j] += r[j]; } } }
    for (c, cc) in cents.iter_mut().zip(&cnt) { if *cc > 0 { for v in c.iter_mut() { *v /= *cc as f64; } } }
    let bgss: f64 = cents.iter().zip(&cnt).filter(|(_, &c)| c > 0)
        .map(|(c, &ct)| c.iter().zip(&g).map(|(a, b)| (a - b) * (a - b)).sum::<f64>() * ct as f64).sum();
    let wgss: f64 = a.iter().enumerate().filter(|&(_, &c)| c < k)
        .map(|(i, &c)| rows[i].iter().zip(&cents[c]).map(|(x, y)| (x - y) * (x - y)).sum::<f64>()).sum();
    if wgss < 1e-10 { return 0.0; }
    (bgss / (k - 1) as f64) / (wgss / (n - k) as f64)
}

#[test]
fn probe_scores() {
    let mut rows = Vec::new();
    for c in 0..3usize {
        for i in 0..10usize {
            let mut row = vec![0.0; 10];
            if c < 10 { row[c] = 10.0; }
            for d in 0..10 { row[d] += (((i * 7 + d * 3 + c * 5) % 11) as f64 - 5.0) * 0.02; }
            rows.push(row);
        }
    }
    for k in [2usize, 3] {
        for t in 0..3u64 {
            let seed = 3407u64.wrapping_add(k as u64 * 1000).wrapping_add(t);
            let a = kmeans_lloyd(&rows, k, 20, seed);
            let mut sizes = vec![0; k];
            for &x in &a { sizes[x.min(k - 1)] += 1; }
            println!("k={k} t={t} seed={seed} ch={:.3} sizes={:?} labels={:?}", ch(&rows, &a, k), sizes, a);
        }
    }
}
